sbx run <<'EOF'
cat > /workspace/fast_eig.c <<'C'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <dlfcn.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef long long i64;
typedef void (*dgeev_fn)(char*, char*, i64*, double*, i64*, double*, double*,
                         double*, i64*, double*, i64*, double*, i64*, i64*,
                         size_t, size_t);

static dgeev_fn g_dgeev = NULL;
static void *g_lib = NULL;

static PyObject *load_lib(PyObject *self, PyObject *args)
{
    const char *path;
    if (!PyArg_ParseTuple(args, "s", &path)) return NULL;
    void *h = dlopen(path, RTLD_NOW | RTLD_LOCAL);
    if (!h) {
        PyErr_Format(PyExc_ImportError, "dlopen failed: %s", dlerror());
        return NULL;
    }
    dgeev_fn f = (dgeev_fn)dlsym(h, "scipy_dgeev_64_");
    if (!f) {
        dlclose(h);
        PyErr_SetString(PyExc_ImportError, "scipy_dgeev_64_ not found");
        return NULL;
    }
    if (g_lib) dlclose(g_lib);
    g_lib = h;
    g_dgeev = f;
    Py_RETURN_NONE;
}

static PyObject *dominant(PyObject *self, PyObject *arg)
{
    if (!g_dgeev) {
        PyErr_SetString(PyExc_RuntimeError, "LAPACK not loaded");
        return NULL;
    }

    PyObject *arr = PyArray_FROM_OTF(arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (!arr) return NULL;
    if (PyArray_NDIM(arr) != 2 || PyArray_DIM(arr, 0) != PyArray_DIM(arr, 1)) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "expected a square 2-D array");
        return NULL;
    }
    npy_intp n = PyArray_DIM(arr, 0);
    if (n < 1) {
        Py_DECREF(arr);
        PyErr_SetString(PyExc_ValueError, "empty matrix");
        return NULL;
    }
    const double *src = (const double *)PyArray_DATA(arr);

    size_t nn = (size_t)n;
    size_t need = 2*nn*nn + 2*nn + nn + 4*nn;
    double *mem = (double *)malloc(need * sizeof(double));
    if (!mem) {
        Py_DECREF(arr);
        return PyErr_NoMemory();
    }
    double *a   = mem;
    double *wr  = a + nn*nn;
    double *wi  = wr + nn;
    double *vr  = wi + nn;
    double *work = vr + nn*nn;
    i64 lwork = (i64)(4*nn + 64*nn + 32);
    if (lwork < 256) lwork = 256;

    /* LAPACK wants column-major */
    for (npy_intp j = 0; j < n; ++j) {
        const double *col = src + j;
        double *dst = a + j*n;
        for (npy_intp i = 0; i < n; ++i) dst[i] = col[i*n];
    }

    char jobvl = 'N', jobvr = 'V';
    i64 nn64 = (i64)n, lda = (i64)n, ldvl = 1, ldvr = (i64)n, info = 0;
    double dummy = 0.0;
    g_dgeev(&jobvl, &jobvr, &nn64, a, &lda, wr, wi, &dummy, &ldvl,
            vr, &ldvr, work, &lwork, &info, (size_t)1, (size_t)1);
    Py_DECREF(arr);
    if (info != 0) {
        free(mem);
        PyErr_SetString(PyExc_RuntimeError, "dgeev failed to converge");
        return NULL;
    }

    npy_intp idx = 0;
    double best = -1.0;
    for (npy_intp i = 0; i < n; ++i) {
        double mag = hypot(wr[i], wi[i]);
        if (mag > best) { best = mag; idx = i; }
    }

    PyObject *vec;
    PyObject *val;
    if (wi[idx] == 0.0) {
        npy_intp dim = n;
        vec = PyArray_SimpleNew(1, &dim, NPY_DOUBLE);
        if (!vec) { free(mem); return NULL; }
        memcpy(PyArray_DATA(vec), vr + idx*ldvr, nn*sizeof(double));
        val = PyFloat_FromDouble(wr[idx]);
    } else {
        npy_intp dim = n;
        vec = PyArray_SimpleNew(1, &dim, NPY_CDOUBLE);
        if (!vec) { free(mem); return NULL; }
        double *out = (double *)PyArray_DATA(vec);
        npy_intp j;
        double sign;
        if (wi[idx] > 0.0) { j = idx; sign = 1.0; }
        else               { j = idx - 1; sign = -1.0; }
        const double *re = vr + j*ldvr;
        const double *im = vr + (j+1)*ldvr;
        for (npy_intp i = 0; i < n; ++i) {
            out[2*i] = re[i];
            out[2*i+1] = sign * im[i];
        }
        val = PyComplex_FromDoubles(wr[idx], wi[idx]);
    }
    free(mem);
    if (!val) { Py_DECREF(vec); return NULL; }
    return Py_BuildValue("NN", val, vec);
}

static PyMethodDef methods[] = {
    {"load_lib", load_lib, METH_VARARGS, "load LAPACK shared library"},
    {"dominant", dominant, METH_O, "dominant eigenpair"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "_fast_eig", NULL, -1, methods
};

PyMODINIT_FUNC PyInit__fast_eig(void)
{
    import_array();
    return PyModule_Create(&moduledef);
}
C
cd /workspace
PYINC=$(python3 -c "import sysconfig;print(sysconfig.get_paths()['include'])")
NPINC=$(python3 -c "import numpy;print(numpy.get_include())")
EXT=$(python3 -c "import sysconfig;print(sysconfig.get_config_var('EXT_SUFFIX'))")
echo "$PYINC $NPINC $EXT"
/workspace/.build/ziglang/zig cc -O3 -fPIC -shared -I"$PYINC" -I"$NPINC" -o "/workspace/_fast_eig$EXT" /workspace/fast_eig.c -ldl 2>&1 | head -40
ls -l /workspace/_fast_eig* /workspace/fast_eig.c
EOF
